// Voxel runner avatar
const avatar=new THREE.Group();scene.add(avatar);
const skin=mat('skin','#e8b786'), shirt=mat('shirt','#e76f51'), pants=mat('pants','#405d79'), boots=mat('boots','#344353'), hair=mat('hair','#594436');
const torso=block(avatar,0,1.05,0,.72,.82,.42,shirt);const head=block(avatar,0,1.77,0,.58,.58,.56,skin);
block(avatar,0,2.03,-.01,.6,.22,.59,hair);
const eyeMat=mat('eyes','#24384b');block(avatar,-.14,1.8,-.292,.075,.09,.025,eyeMat,false);block(avatar,.14,1.8,-.292,.075,.09,.025,eyeMat,false);
const armL=new THREE.Group();armL.position.set(-.48,1.36,0);avatar.add(armL);block(armL,0,-.28,0,.27,.68,.3,shirt);block(armL,0,-.59,0,.27,.25,.3,skin);
const armR=new THREE.Group();armR.position.set(.48,1.36,0);avatar.add(armR);block(armR,0,-.28,0,.27,.68,.3,shirt);block(armR,0,-.59,0,.27,.25,.3,skin);
const legs=[];
for(const side of [-1,1]){const leg=new THREE.Group();leg.position.set(side*.19,.68,0);avatar.add(leg);block(leg,0,-.27,0,.31,.64,.34,pants);block(leg,0,-.61,-.04,.33,.2,.4,boots);legs.push(leg)}

const player={x:0,z:0,y:.14,vx:0,vy:0,vz:0,ground:true,jumps:0,face:0};
let checkpointIndex=0,falls=0,started=false,finished=false,startTime=0,elapsed=0,toastTimeout;
let respawn={x:0,y:.15,z:0,face:0};
const timerEl=document.getElementById('timer'),bestEl=document.getElementById('best'),fallsEl=document.getElementById('falls'),progressEl=document.getElementById('progress'),progressText=document.getElementById('progressText');
const savedBest=Number(localStorage.getItem('blockbound-best')||0);
const timeString=t=>{const whole=Math.max(0,t),m=Math.floor(whole/60),s=Math.floor(whole%60),d=Math.floor((whole%1)*10);return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}.${d}`};
bestEl.textContent=savedBest?timeString(savedBest):'--:--.-';
const keys={};
addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k===' '||k==='arrowup')jump();if(k==='r'&&started)respawnPlayer(false);});
addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
document.querySelectorAll('[data-key]').forEach(btn=>{
 const key=btn.dataset.key;
 const down=e=>{e.preventDefault();keys[key]=true;btn.classList.add('down');if(key==='space')jump();};
 const up=e=>{e.preventDefault();keys[key]=false;btn.classList.remove('down')};
 btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointerleave',up);btn.addEventListener('pointercancel',up);
});
let pointerDown=false,lastPX=0,lastPY=0,yaw=0,pitch=.12;
renderer.domElement.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button===0){pointerDown=true;lastPX=e.clientX;lastPY=e.clientY;renderer.domElement.setPointerCapture(e.pointerId)}});
renderer.domElement.addEventListener('pointermove',e=>{if(pointerDown){yaw-= (e.clientX-lastPX)*.004;pitch=THREE.MathUtils.clamp(pitch-(e.clientY-lastPY)*.002,-.2,.65);lastPX=e.clientX;lastPY=e.clientY}});
renderer.domElement.addEventListener('pointerup',()=>pointerDown=false);
// Touch drag look works in the open playfield without obstructing the on-screen controls.
let touchLook=null;
renderer.domElement.addEventListener('touchstart',e=>{if(e.touches.length){const t=e.touches[0];if(t.clientY<innerHeight-190){touchLook=[t.clientX,t.clientY]}}},{passive:true});
renderer.domElement.addEventListener('touchmove',e=>{if(touchLook&&e.touches.length){const t=e.touches[0];yaw-=(t.clientX-touchLook[0])*.004;pitch=THREE.MathUtils.clamp(pitch-(t.clientY-touchLook[1])*.002,-.2,.65);touchLook=[t.clientX,t.clientY]}},{passive:true});
renderer.domElement.addEventListener('touchend',()=>touchLook=null);
function jump(){if(!started||finished)return;if(player.jumps<2){player.vy=player.jumps===0?8.3:7.6;player.ground=false;player.jumps++;}}
document.getElementById('play').addEventListener('click',()=>{document.getElementById('overlay').classList.add('hidden');started=true;startTime=performance.now();renderer.domElement.focus()});
function showToast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>t.classList.remove('show'),1700)}
function respawnPlayer(countFall=true){if(countFall){falls++;fallsEl.textContent=falls;}player.x=respawn.x;player.y=respawn.y;player.z=respawn.z;player.vx=player.vy=player.vz=0;player.jumps=0;player.ground=true;yaw=0;showToast('BACK TO THE CHECKPOINT!')}
const solids=[...platforms,...stepping];
function floorAt(x,z){let floor=-Infinity;for(const p of solids){if(Math.abs(x-p.x)<p.w/2+.24&&Math.abs(z-p.z)<p.d/2+.24)floor=Math.max(floor,p.y+.12);}return floor}
const clock=new THREE.Clock();let walkClock=0;
function update(dt){
 if(!started||finished)return;
 elapsed=(performance.now()-startTime)/1000;timerEl.textContent=timeString(elapsed);
 const forward=(keys.w||keys.arrowup?1:0)-(keys.s||keys.arrowdown?1:0),side=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);
 const fast=keys.shift?1.48:1,accel=28,friction=Math.exp(-9*dt);
 // camera yaw sets movement frame; default course direction is +X
 const heading=yaw;const fx=Math.cos(heading),fz=Math.sin(heading),rx=-fz,rz=fx;
 let dx=fx*forward+rx*side,dz=fz*forward+rz*side;const len=Math.hypot(dx,dz);if(len>0){dx/=len;dz/=len;player.vx+=dx*accel*dt;player.vz+=dz*accel*dt;player.face=Math.atan2(-dz,dx)}else{player.vx*=friction;player.vz*=friction}
 const maxSpeed=keys.shift?8.5:5.7,hs=Math.hypot(player.vx,player.vz);if(hs>maxSpeed){player.vx=player.vx/hs*maxSpeed;player.vz=player.vz/hs*maxSpeed;}
 const oldBottom=player.y;player.x+=player.vx*dt;player.z+=player.vz*dt;player.vy-=19*dt;player.y+=player.vy*dt;
 const floor=floorAt(player.x,player.z);
 if(floor>-Infinity&&player.vy<=0&&oldBottom>=floor-.13&&player.y<=floor){player.y=floor;player.vy=0;player.ground=true;player.jumps=0}else player.ground=false;
 if(player.y < -18)respawnPlayer(true);
 avatar.position.set(player.x,player.y,player.z);avatar.rotation.y=player.face;
 walkClock+=dt*(hs*.95);const walking=player.ground&&hs>.5?1:0;legs[0].rotation.x=Math.sin(walkClock)*.55*walking;legs[1].rotation.x=-Math.sin(walkClock)*.55*walking;armL.rotation.x=-Math.sin(walkClock)*.42*walking;armR.rotation.x=Math.sin(walkClock)*.42*walking;
 // Checkpoint progress is saved only by landing on the checkpoint island.
 while(checkpointIndex<checkpoints.length){const cp=checkpoints[checkpointIndex],p=platforms.find(q=>q.id===cp.platform);if(p&&Math.abs(player.x-p.x)<p.w/2&&Math.abs(player.z-p.z)<p.d/2&&player.y<=p.y+.3&&player.y>=p.y-.1){checkpointIndex++;respawn={x:p.x,y:p.y+.15,z:p.z,face:0};progressText.textContent=`CHECKPOINT ${checkpointIndex} / 4`;progressEl.style.width=`${checkpointIndex/4*100}%`;showToast(checkpointIndex===4?'FINAL CHECKPOINT!':'CHECKPOINT SAVED!');}else break;}
 if(player.x>87&&Math.abs(player.z-1)<3&&player.y>12){finished=true;const record=!savedBest||elapsed<savedBest;if(record)localStorage.setItem('blockbound-best',elapsed);showToast(record?'NEW BEST! GATE REACHED!':'GATE REACHED!');setTimeout(()=>{document.querySelector('.eyebrow').textContent='RUN COMPLETE · '+timeString(elapsed);document.querySelector('.title').innerHTML='YOU<br><span>MADE IT.</span>';document.querySelector('.subtitle').textContent=`A flawless-ish flight across the sky. You finished in ${timeString(elapsed)} with ${falls} fall${falls===1?'':'s'}. Ready to beat that?`;document.querySelector('.play').textContent='RUN IT BACK  →';document.querySelector('.play').onclick=()=>location.reload();document.getElementById('overlay').classList.remove('hidden')},1200)}
 // camera trails behind the runner with a little look-ahead
 const camYaw=yaw;const backX=Math.cos(camYaw),backZ=Math.sin(camYaw);
 const desired=new THREE.Vector3(player.x-9*backX,player.y+6.1+pitch*4,player.z-9*backZ);
 camera.position.lerp(desired,1-Math.exp(-4.2*dt));camera.lookAt(player.x+3.1*backX,player.y+1.05,player.z+3.1*backZ);
}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.035);update(dt);const t=performance.now()*.001;for(let i=0;i<flagPoles.length;i++)flagPoles[i].children[1].rotation.y=Math.sin(t*2+i)*.12;gate.rotation.y=Math.sin(t*.6)*.035;renderer.render(scene,camera)}
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.65))});
animate();
</script>
</body>
</html>

